solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
size_t strain_values(const void *in, size_t n, size_t size, value_predicate fn,
                     bool keep, void *out) {
    size_t k = 0;
    for (size_t i = 0; i < n; i++)
        if (fn((const unsigned char *)in + i * size) == keep) {
            memcpy((unsigned char *)out + k * size,
                   (const unsigned char *)in + i * size, size);
            k++;
        }
    return k;
}
size_t strain(const int *in, size_t n, predicate fn, bool keep, int *out) {
    size_t k = 0;
    for (size_t i = 0; i < n; i++)
        if (fn(in[i]) == keep)
            out[k++] = in[i];
    return k;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    int a[] = {-3, 0, 2, 4}, o[4];
    assert(strain(a, 4, positive, true, o) == 2 && o[0] == 2 && o[1] == 4);
    assert(strain(a, 4, positive, false, o) == 2 && o[0] == -3 && o[1] == 0);
    assert(strain(NULL, 0, NULL, true, NULL) == 0);
    const char *words[] = {"apple", "banana", "blueberry"}, *kept[3];
    assert(strain_values(words, 3, sizeof words[0], bstring, true, kept) == 2 &&
           !strcmp(kept[0], "banana") && !strcmp(kept[1], "blueberry"));

    return 0;
}
